    lines = []
    current = []
    cur_len = 0
    for w in words:
        if not current:
            # start a new line with this word (even if longer than width)
            current.append(w)
            cur_len = len(w)
        else:
            # need space before word
            if cur_len + 1 + len(w) <= width:
                current.append(w)
                cur_len += 1 + len(w)
            else:
                # finish current line
