def solve(grid):
    """Count islands (connected components of 1s) in a possibly irregular binary grid.
    Connectivity is 4-directional (up, down, left, right). Works even if rows have
    different lengths or the grid is empty.
    """
    if not grid:
        return 0
    rows = len(grid)
    # visited mirrors the shape of grid
    visited = [ [False]*len(row) for row in grid ]
    def dfs(r, c):
        stack = [(r, c)]
        while stack:
            i, j = stack.pop()
            if visited[i][j]:
                continue
            visited[i][j] = True
            # neighbours: up, down, left, right
            # up
            if i > 0 and j < len(grid[i-1]) and not visited[i-1][j] and grid[i-1][j] == 1:
                stack.append((i-1, j))
            # down
            if i+1 < rows and j < len(grid[i+1]) and not visited[i+1][j] and grid[i+1][j] == 1:
                stack.append((i+1, j))
            # left
            if j > 0 and not visited[i][j-1] and grid[i][j-1] == 1:
                stack.append((i, j-1))
            # right
            if j+1 < len(grid[i]) and not visited[i][j+1] and grid[i][j+1] == 1:
                stack.append((i, j+1))
    count = 0
    for i, row in enumerate(grid):
        for j, val in enumerate(row):
            if val == 1 and not visited[i][j]:
                count += 1
                dfs(i, j)
    return count

