import string

def solve(n, b):
    if n == 0:
        return '0'
    digits = string.digits + string.ascii_lowercase
    neg = n < 0
    n = abs(n)
    out = []
    while n:
        out.append(digits[n % b])
        n //= b
    if neg:
        out.append('-')
    return ''.join(reversed(out))

