def solve(matrix):
    m = [list(row) for row in matrix]

    def det(a):
        n = len(a)
        if n == 1:
            return a[0][0]
        if n == 2:
            return a[0][0] * a[1][1] - a[0][1] * a[1][0]
        total = 0
        for j in range(n):
            minor = [row[:j] + row[j + 1:] for row in a[1:]]
            sign = 1 if j % 2 == 0 else -1
            total += sign * a[0][j] * det(minor)
        return total

    return det(m)

